from pathlib import Path
from playwright.sync_api import sync_playwright
from html import escape
root=Path(__file__).resolve().parent
style='''<style>*{box-sizing:border-box}body{margin:0;background:#f4f7fc;color:#1c2940;font-family:Arial,sans-serif}.layout{display:flex;min-height:740px}aside{width:240px;background:#142947;color:white;padding:30px 16px}.brand{font-weight:bold;font-size:22px;margin-bottom:45px}nav div{padding:13px;border-radius:8px;color:#cbdcf4}nav .active{background:#2b4771;color:white}main{padding:40px;width:960px}h1{font-size:30px;margin:8px 0 25px}h2{font-size:19px;margin:0 0 20px}.hint{color:#687991;font-size:13px}.banner{background:#fff4d7;color:#79571c;border:1px solid #f3d38b;padding:12px;border-radius:9px;margin-bottom:20px}.cards{display:flex;gap:14px}.card,section{background:white;border:1px solid #e2e8f1;border-radius:14px;padding:23px;margin-bottom:16px}.card{width:33%}.card b{display:block;font-size:28px;margin-top:14px}.green{color:#14805a}.red{color:#d35445}table{width:100%;border-collapse:collapse;background:white}th,td{padding:16px;border-bottom:1px solid #edf0f5;text-align:left}th{color:#697b91;font-size:13px}.badge{background:#fff0e8;color:#ad4c22;padding:7px 12px;border-radius:20px}.ok{background:#e1f6e9;color:#137548}.button{background:#2563eb;color:white;padding:10px 15px;border-radius:8px;display:inline-block}.row{display:flex;justify-content:space-between;align-items:center}.choice{border:1px solid #dce4ef;border-radius:8px;padding:13px 18px;margin-right:10px;display:inline-block}.line{padding:15px 0;border-top:1px solid #e9edf3}</style>'''
nav=['Pulpit','Zbiórki i wpłaty','Ankiety','Sprawy organizacyjne','Raporty','Ustawienia']
def page(title,body):
 n=''.join('<div class="'+('active' if x==title else '')+'">'+escape(x)+'</div>' for x in nav)
 return f'<!doctype html><html lang="pl"><meta charset="utf-8">{style}<div class="layout"><aside><div class="brand">🏫 Przedszkolny<br>Organizer</div><nav>{n}</nav></aside><main><div class="hint">Przedszkole demonstracyjne / Grupa Sówki</div><h1>{escape(title)}</h1><div class="banner">Wizualizacja dokumentacyjna na danych fikcyjnych — nie jest zrzutem działającego wdrożenia.</div>{body}</main></div></html>'
pages={
'pulpit':('Pulpit','<div class="cards"><div class="card">Łącznie do zebrania<b>400,00 zł</b></div><div class="card">Wpłacono<b class="green">215,00 zł</b></div><div class="card">Pozostało<b class="red">185,00 zł</b></div></div><section><h2>Aktywne zbiórki</h2><div class="line row"><span><b>Wycieczka</b><p class="hint">Termin: 2026-11-20 · 50 zł / dziecko</p></span><span class="button">Szczegóły →</span></div><div class="line row"><span><b>Mikołajki</b><p class="hint">Termin: 2026-12-01 · 30 zł / dziecko</p></span><span class="button">Szczegóły →</span></div></section>'),
'wplaty':('Zbiórki i wpłaty','<section><div class="row"><h2>Wycieczka · 50,00 zł / dziecko</h2><span class="button">+ Nowa zbiórka</span></div><p class="hint">Termin: 2026-11-20</p><table><tr><th>Dziecko</th><th>Wpłacono</th><th>Pozostało</th><th>Status</th></tr><tr><td>Anna K.</td><td>50,00 zł</td><td>0,00 zł</td><td><span class="badge ok">Opłacono</span></td></tr><tr><td>Jan M.</td><td>0,00 zł</td><td>50,00 zł</td><td><span class="badge">Brak</span></td></tr><tr><td>Ola P.</td><td>50,00 zł</td><td>0,00 zł</td><td><span class="badge ok">Opłacono</span></td></tr><tr><td>Maja W.</td><td>25,00 zł</td><td>25,00 zł</td><td><span class="badge">Częściowo</span></td></tr><tr><td>Adam S.</td><td>0,00 zł</td><td>50,00 zł</td><td><span class="badge">Brak</span></td></tr></table></section>'),
'ankiety':('Ankiety','<section><h2>Nowa ankieta</h2><p class="hint">Pytanie</p><div class="choice" style="width:90%">Czy organizujemy piknik rodzinny?</div><p class="hint">Odpowiedzi</p><div class="choice">Tak</div><div class="choice">Nie</div><p><span class="button">Utwórz ankietę</span></p></section><section><h2>Czy organizujemy piknik rodzinny?</h2><p>Oddaj demonstracyjny głos:</p><span class="choice">Tak</span><span class="choice">Nie</span></section>'),
'organizacja':('Sprawy organizacyjne','<section><h2>Dodaj ogłoszenie / wydarzenie</h2><p class="hint">Tytuł</p><div class="choice" style="width:90%">Zebranie rodziców</div><p class="hint">Opis</p><div class="choice" style="width:90%">Spotkanie organizacyjne w sali grupy.</div><p><span class="button">Dodaj</span></p></section><section><h2>Zebranie rodziców</h2><p>Spotkanie organizacyjne w sali grupy.</p><p class="hint">📅 2026-11-18</p></section>')}
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/opt/pw-browsers/chromium-1228/chrome-linux64/chrome',headless=True,args=['--no-sandbox'])
 for slug,(title,body) in pages.items():
  tab=browser.new_page(viewport={'width':1200,'height':780},device_scale_factor=1)
  tab.set_content(page(title,body));tab.screenshot(path=str(root/'screenshots'/f'{slug}.png'),full_page=True);tab.close()
 browser.close()
